/* 1920×1080 固定画布。抖音那边的教训照搬：不用 CSS 滤镜（每次换图都要重新光栅化，和解码器抢 GPU）；
 * 要整块移动的内容常驻一个合成层（will-change: transform）；焦点放大不做过渡。 */
html, body { margin: 0; width: 1920px; height: 1080px; overflow: hidden; background: #0b0d10; color: #e8eaed;
             font-family: "Samsung One", "Noto Sans CJK SC", sans-serif; }
.hide { display: none !important; }

/* ---------- 主页 ---------- */
#home { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; }
/* 左边的来源栏：浏览视频时收起来，按左键滑出来盖在网格上（用户 2026-10-01） */
#rail { position: absolute; left: 0; top: 0; width: 380px; height: 1080px; background: #12161b; z-index: 3;
        transform: translateX(-380px); transition: transform 0.15s ease-out; will-change: transform; }
#home.railopen #rail { transform: translateX(0); box-shadow: 12px 0 40px rgba(0, 0, 0, 0.6); }
#dim { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; background: #000; opacity: 0; z-index: 2;
       transition: opacity 0.15s; pointer-events: none; }
#home.railopen #dim { opacity: 0.55; }
#brand { height: 120px; line-height: 120px; padding-left: 48px; font-size: 40px; font-weight: bold; color: #2aabee; }
#rail-wrap { position: absolute; top: 120px; left: 0; width: 380px; height: 930px; overflow: hidden; }
#rail-list { will-change: transform; }
.src { height: 72px; line-height: 72px; padding: 0 28px 0 48px; font-size: 30px; white-space: nowrap; overflow: hidden;
       text-overflow: ellipsis; color: #aeb4bb; border-left: 6px solid transparent; }
.src .k { font-size: 22px; color: #6b737c; margin-right: 10px; }
.src.cur { color: #fff; border-left-color: #2aabee; }
.src.focus { background: #2aabee; color: #fff; }
.src.focus .k { color: #dff3ff; }

#main { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; }
/* 浏览页不要顶栏（用户 2026-10-01：不需要展示群名），群名只在左边来源栏里 */
#head { display: none; }
#src-hint { position: absolute; right: 60px; top: 46px; font-size: 24px; color: #5f6770; }
#src-title { font-size: 44px; padding-top: 30px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#src-sub { font-size: 24px; color: #7d858e; margin-top: 6px; }
#grid-wrap { position: absolute; top: 50px; left: 0; width: 1920px; height: 1030px; overflow: hidden; }
#grid { position: relative; will-change: transform; }
.card { position: absolute; width: 576px; height: 450px; }
.thumb { position: relative; width: 576px; height: 324px; background: #1c2128; border-radius: 10px; overflow: hidden; }
.thumb img { position: absolute; left: 0; top: 0; width: 100%; height: 100%; object-fit: cover; display: block; }
/* 没缩略图的片子（不少大文件转发过来就没有）：片名当封面 */
.ph { position: absolute; left: 0; top: 0; width: 100%; height: 100%; box-sizing: border-box; padding: 0 40px; display: flex;
      align-items: center; justify-content: center; text-align: center; overflow: hidden; }
.ph span { font-size: 42px; line-height: 1.3; font-weight: bold; color: rgba(255, 255, 255, 0.92); letter-spacing: 2px;
           text-shadow: 0 2px 12px rgba(0, 0, 0, 0.5); max-height: 165px; overflow: hidden; }
/* 海报卡片：海报完整居中（2:3，卡片高 324 → 宽 216），两边是同一张海报缩小再拉伸的底图，压暗一点；底下的片名占位文字藏起来 */
.thumb.hasposter .ph span { display: none; }
.pbg { position: absolute; left: 0; top: 0; width: 100%; height: 100%; background-size: cover; background-position: center; opacity: 0.55; }
.thumb img.pimg { left: 180px; width: 216px; height: 324px; object-fit: cover; box-shadow: 0 0 30px rgba(0, 0, 0, 0.6); }
.dur { position: absolute; z-index: 1; right: 8px; bottom: 10px; background: rgba(0, 0, 0, 0.75); color: #fff; font-size: 20px;
       padding: 2px 8px; border-radius: 4px; }
.prog { position: absolute; z-index: 1; left: 0; bottom: 0; height: 6px; background: #2aabee; }
.title { font-size: 30px; line-height: 40px; margin-top: 14px; max-height: 80px; overflow: hidden;
         display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.meta { font-size: 24px; color: #7d858e; margin-top: 4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.card.focus .thumb { box-shadow: 0 0 0 5px #2aabee; }
.card.focus .title { color: #fff; }
#empty { position: absolute; top: 300px; left: 60px; width: 1700px; font-size: 34px; line-height: 1.7; color: #9aa1a9; }
#empty b { color: #2aabee; }

/* ---------- 播放器 ---------- */
#player { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; background: #000; display: none; }
#player.on { display: block; }
video { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; background: #000; }
#ov { position: absolute; left: 0; bottom: 0; width: 1920px; height: 260px; opacity: 0.99;
      background: linear-gradient(to bottom, rgba(0, 0, 0, 0), rgba(0, 0, 0, 0.85)); display: none; }
#ov.on { display: block; }
#ov-title { position: absolute; left: 80px; top: 70px; width: 1760px; font-size: 38px; white-space: nowrap; overflow: hidden;
            text-overflow: ellipsis; text-shadow: 0 0 6px #000; }
#ov-bar { position: absolute; left: 80px; top: 145px; width: 1760px; height: 8px; background: rgba(255, 255, 255, 0.25); border-radius: 4px; }
#ov-buf { position: absolute; left: 0; top: 0; height: 8px; background: rgba(255, 255, 255, 0.35); border-radius: 4px; }
#ov-fill { position: absolute; left: 0; top: 0; height: 8px; background: #2aabee; border-radius: 4px; }
#ov-dot { position: absolute; top: -8px; width: 24px; height: 24px; margin-left: -12px; background: #fff; border-radius: 12px; }
#ov-row { position: absolute; left: 80px; top: 180px; width: 1760px; font-size: 28px; color: #d0d4d8; }
#ov-keys { float: right; color: #8b939b; font-size: 24px; }
#seekhint { position: absolute; left: 0; top: 440px; width: 1920px; text-align: center; font-size: 64px; font-weight: bold;
            text-shadow: 0 0 12px #000; display: none; }
#spin { position: absolute; left: 0; top: 460px; width: 1920px; text-align: center; display: none; }
#spin.on { display: block; }
#spin .ring { width: 72px; height: 72px; margin: 0 auto; border: 8px solid rgba(255, 255, 255, 0.2); border-top-color: #2aabee;
              border-radius: 50%; animation: rot 0.9s linear infinite; }
#spin-text { margin-top: 24px; font-size: 28px; color: #c5cad0; text-shadow: 0 0 6px #000; }
@keyframes rot { to { transform: rotate(360deg); } }
/* ---------- 字幕（subs.js） ---------- */
/* 文字字幕：底部居中，白字黑边（text-shadow 一圈，不用滤镜）；进度条浮层出来时整体抬到它上面（#player.ovon） */
#sub { position: absolute; left: 140px; width: 1640px; bottom: 64px; text-align: center; font-size: 54px; line-height: 1.32;
       color: #fff; white-space: pre-line; pointer-events: none; font-weight: 600;
       text-shadow: -3px -3px 0 #000, 3px -3px 0 #000, -3px 3px 0 #000, 3px 3px 0 #000, 0 3px 0 #000, 0 -3px 0 #000, 3px 0 0 #000, -3px 0 0 #000, 0 0 10px #000; }
/* 要放在上面的（ASS 的 \an7–9、标牌字幕） */
#subtop { position: absolute; left: 140px; width: 1640px; top: 56px; text-align: center; font-size: 46px; line-height: 1.32;
          color: #fff; white-space: pre-line; pointer-events: none; font-weight: 600;
          text-shadow: -3px -3px 0 #000, 3px -3px 0 #000, -3px 3px 0 #000, 3px 3px 0 #000, 0 3px 0 #000, 0 -3px 0 #000, 3px 0 0 #000, -3px 0 0 #000, 0 0 10px #000; }
#player.ovon #sub { bottom: 280px; }
#subpic { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; pointer-events: none; }

#perr { position: absolute; left: 200px; top: 400px; width: 1520px; text-align: center; font-size: 36px; line-height: 1.6;
        display: none; }

/* ---------- 登录 ---------- */
#panel { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; background: #101418; display: none; }
#panel.on { display: block; }
#qr { position: absolute; left: 1180px; top: 190px; width: 620px; height: 620px; background: #fff; }
#qr svg { width: 100%; height: 100%; display: block; }
#how { position: absolute; left: 120px; top: 260px; width: 960px; font-size: 40px; line-height: 1.6; }
#how b { color: #2aabee; }
#qrstate { color: #999; font-size: 30px; margin-top: 30px; }
#pwbox { position: absolute; left: 120px; top: 640px; display: none; font-size: 34px; }
#pwbox.on { display: block; }
#pw { font-size: 40px; width: 700px; padding: 10px; margin-top: 16px; }

#toast { position: absolute; left: 0; bottom: 70px; width: 1920px; text-align: center; display: none; }
/* 播放时提示条放上面：底下是字幕的位置 */
#player.on ~ #toast { bottom: auto; top: 60px; }
#toast span { display: inline-block; background: rgba(30, 36, 44, 0.95); color: #fff; font-size: 30px; padding: 16px 36px; border-radius: 40px; }
#lines { position: absolute; left: 40px; top: 20px; width: 1300px; font-size: 20px; line-height: 1.4; color: #ffd27a;
         text-shadow: 0 0 4px #000; pointer-events: none; }

/* ---------- 播放器里的菜单（长按确认键）---------- */
#menu { position: absolute; right: 0; top: 0; width: 720px; height: 1080px; background: rgba(14, 17, 21, 0.95); display: none;
        box-shadow: -12px 0 40px rgba(0, 0, 0, 0.6); }
#menu.on { display: block; }
#menu-wrap { position: absolute; left: 0; top: 0; width: 720px; height: 980px; overflow: hidden; }
#menu-list { padding-top: 36px; will-change: transform; }
#menu .mh { font-size: 26px; color: #7d858e; padding: 26px 48px 8px; }
#menu .mi { font-size: 32px; height: 68px; line-height: 68px; padding: 0 40px 0 48px; white-space: nowrap; overflow: hidden;
            text-overflow: ellipsis; color: #d0d4d8; }
#menu .mi .ck { display: inline-block; width: 44px; color: #2aabee; }
#menu .mi.dis { color: #5a626b; }
#menu .mi.focus { background: #2aabee; color: #fff; }
#menu .mi.focus .ck { color: #fff; }
#menu-foot { position: absolute; left: 48px; bottom: 34px; font-size: 24px; color: #6b737c; }

/* 放完了、有下一集：右下角倒计时 */
#upnext { position: absolute; right: 80px; bottom: 110px; width: 760px; background: rgba(14, 17, 21, 0.94); border-radius: 14px;
          padding: 30px 40px; display: none; box-shadow: 0 0 40px rgba(0, 0, 0, 0.6); }
#upnext.on { display: block; }
#upnext .h { font-size: 26px; color: #8b939b; }
#upnext .t { font-size: 40px; margin-top: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#upnext .k { font-size: 26px; color: #8b939b; margin-top: 18px; }

/* 搜索 */
#sx { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; background: rgba(10, 13, 16, 0.96); display: none; }
#sx.on { display: block; }
#sx .box { position: absolute; left: 460px; top: 150px; width: 1000px; }
#sx .h { font-size: 56px; margin-bottom: 24px; }
#sx .sub { font-size: 28px; line-height: 1.6; color: #8b939b; margin-bottom: 36px; }
#sx input { font-size: 44px; width: 960px; padding: 14px 18px; border: 3px solid #3a424b; border-radius: 10px; background: #1b2128; color: #fff; outline: none; }
#sx input:focus { border-color: #2aabee; }
#sx .lab { font-size: 26px; color: #7d858e; margin: 40px 0 12px; }
#sx-recent .q { display: inline-block; font-size: 30px; padding: 10px 26px; margin: 0 16px 16px 0; border-radius: 30px; background: #1b2128; color: #c5cad0; }
#sx-recent .q.focus { background: #2aabee; color: #fff; }

/* 账号 */
#acct { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; background: rgba(10, 13, 16, 0.96); display: none; }
#acct.on { display: block; }
#acct .box { position: absolute; left: 460px; top: 150px; width: 1000px; }
#acct .h { font-size: 56px; margin-bottom: 24px; }
#acct .sub { font-size: 28px; line-height: 1.6; color: #8b939b; margin-bottom: 36px; }
#acct .ai { font-size: 36px; height: 84px; line-height: 84px; padding: 0 30px; border-radius: 10px; color: #d0d4d8;
            white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#acct .ai .ck { display: inline-block; width: 54px; color: #2aabee; }
#acct .ai.sep { margin-top: 24px; }
#acct .ai.focus { background: #2aabee; color: #fff; }
#acct .ai.focus .ck { color: #fff; }
#qrnote { color: #f0b429; font-size: 30px; margin-top: 20px; }

/* 设置：和账号页一个样子，下面两行状态 */
#opts { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; background: rgba(10, 13, 16, 0.96); display: none; }
#opts.on { display: block; }
#opts .box { position: absolute; left: 460px; top: 150px; width: 1000px; }
#opts .h { font-size: 56px; margin-bottom: 36px; }
#opts .ai { font-size: 36px; height: 84px; line-height: 84px; padding: 0 30px; border-radius: 10px; color: #d0d4d8; }
#opts .ai.sep { margin-top: 24px; }
#opts .ai.focus { background: #2aabee; color: #fff; }
#opts .st { font-size: 28px; line-height: 1.5; color: #c5cad0; margin-top: 24px; min-height: 42px; }
#opts .sub { font-size: 26px; line-height: 1.6; color: #8b939b; margin-top: 40px; }

/* 第一次打开：填 API ID / Hash（apikey.js）。和网页登录一个样子，右边多一个去 my.telegram.org 的码 */
#api { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; background: #101418; display: none; }
#api.on { display: block; }
#api .box { position: absolute; left: 120px; top: 120px; width: 1060px; }
#api .h { font-size: 56px; margin-bottom: 24px; }
#api .sub { font-size: 28px; line-height: 1.6; color: #8b939b; margin-bottom: 30px; }
#api .lab { font-size: 30px; color: #c5cad0; margin: 24px 0 10px; }
#api input { font-size: 40px; width: 1020px; padding: 14px 18px; border: 3px solid #3a424b; border-radius: 10px; background: #1b2128; color: #fff; outline: none; font-family: monospace; }
#api input:focus { border-color: #2aabee; }
#api-msg { font-size: 30px; color: #f0b429; margin-top: 30px; min-height: 40px; line-height: 1.5; }
#api-qr { position: absolute; left: 1320px; top: 240px; width: 480px; height: 480px; background: #fff; }
#api-qr svg { width: 100%; height: 100%; display: block; }
#api-url { position: absolute; left: 1320px; top: 750px; width: 480px; text-align: center; font-size: 32px; color: #2aabee; }

/* 网页登录 */
#wl { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; background: rgba(10, 13, 16, 0.94); display: none; }
#wl.on { display: block; }
#wl .box { position: absolute; left: 460px; top: 170px; width: 1000px; }
#wl .h { font-size: 56px; margin-bottom: 24px; }
#wl .sub { font-size: 28px; line-height: 1.6; color: #8b939b; margin-bottom: 40px; }
#wl .lab { font-size: 30px; color: #c5cad0; margin: 24px 0 10px; }
#wl input { font-size: 40px; width: 960px; padding: 14px 18px; border: 3px solid #3a424b; border-radius: 10px; background: #1b2128; color: #fff; outline: none; }
#wl input:focus { border-color: #2aabee; }
#wl-msg { font-size: 30px; color: #f0b429; margin-top: 30px; min-height: 40px; }

files.js/diag.js:
/* 诊断日志：别人电视上的问题传回给开发者（2026-10-21，照搬 douyin-tizen / bilibili-tizen 的 diag.js）。
 *
 * 8097 上的收集器（tools/collect.mjs）只有开发构建有。装了发布包的电视出了事，开发者这边一个字都看不到。
 * 所以每一行日志同时记进这里的一圈（记的时候就去掉身份），出了观众看得见的事（Diag.incident）、或者观众在
 * 来源栏的「设置」里按「上传诊断日志」时，把这一圈传上去。默认开，「设置」里能关；关了就什么都不记、不存、不传。
 *
 * 永远不离开电视的：群和频道的名字、片名和文件名、字幕文件名、账号的名字和 Telegram 用户 ID、搜索词、网页地址和网站
 * 账号编号、API ID / Hash、扫码登录的 tg:// 链接。调用处把名字包进 Diag.priv()，上传时换成「…」；scrub() 里的规则兜住
 * 容易忘的形状：日志里「」括起来的一律当名字（这个项目写日志的习惯就是这么括的）、任何 http(s):// 和 tg:// 地址、
 * id=<数字>、32 位以上的十六进制串。视频本身的编号（消息 id）不在日志里，片子靠时长、大小、编码分。
 *
 * 接收端是 bilibili-tizen 的 server/diag-worker.mjs（三个应用共用，按 app 分开），读用那边的
 * tools/diag-logs.mjs --app telegram-tizen。这个文件随每个更新包下发，所以接收地址和去隐私的规则都能靠更新修；
 * config.js 不随更新下发，所以地址写在这里。ES5，和 app/js 里的一切一样。 */
var Diag = (function () {
    "use strict";

    var ENDPOINT = "https://diag.titdev.nl/v1/upload";   /* bilibili-tizen/server/README.md */
    var APP = "telegram-tizen";

    var K_RING = "tg.diag.ring", K_DEVICE = "tg.diag.device", K_SENT = "tg.diag.sent", K_OFF = "tg.diag.off";

    /* 600 行大约是一部片子从起播到放弃的全部，加上之前那次启动；字数上限让 localStorage 占用在 300KB 上下
     * （UTF-16），和同一份配额里的更新包（约 400KB）、看到哪里的记录都离得远。 */
    var MAX_LINES = 600, MAX_CHARS = 160000, MAX_LINE = 4000;
    var SETTLE = 8000;          /* 出事之后等一会儿，让解释它的那几行（重试、换路）也进来 */
    var AUTO_GAP = 180000;      /* 自动上传最多三分钟一份…… */
    var AUTO_PER_DAY = 12;      /* ……一天十二份：卡在循环里的电视不能变成水龙头 */
    var MANUAL_GAP = 10000;
    var PERSIST_EVERY = 15000;

    var OPEN = "\uE000", CLOSE = "\uE001";   /* 私用区的两个字符：日志里不会自然出现 */

    var report = function () {};
    var ring = [], chars = 0, loaded = false;
    var persistTimer = null, settleTimer = null, reasons = [], sending = false;
    var last = null;            /* {at, ok, id, why, manual} —— 这次启动最近一次上传，设置页那行字用 */

    function get(k) { try { return localStorage.getItem(k); } catch (e) { return null; } }
    function put(k, v) { try { localStorage.setItem(k, v); return true; } catch (e) { return false; } }
    function del(k) { try { localStorage.removeItem(k); } catch (e) {} }
    function parse(s) { try { return s ? JSON.parse(s) : null; } catch (e) { return null; } }
    function now() { return new Date().getTime(); }

    /* 开关直接记在 localStorage（这台电视的设置，不跟账号走）。 */
    function enabled() { return get(K_OFF) !== "1"; }

    /* 开发构建（REPORT_TO 非空，自测构建也是）有收集器，什么都不传 —— 除非 deploy.sh 给了地址
     * （TG_DIAG_TO → config.js 的 DIAG_TO），在电视上测上传这条路就靠它。比这个文件老的安装包里，
     * config.js 没有 DIAG_TO，所以用 typeof。 */
    function endpoint() {
        var override = typeof DIAG_TO !== "undefined" ? DIAG_TO : "";
        if (override) { return override; }
        var dev = typeof REPORT_TO !== "undefined" && !!REPORT_TO;
        return dev ? "" : ENDPOINT;
    }

    /* ---------------- 什么能传出去 ---------------- */

    function priv(s) {
        return OPEN + String(s == null ? "" : s).replace(/[\uE000\uE001]/g, "") + CLOSE;
    }
    function plain(s) { return String(s == null ? "" : s).replace(/[\uE000\uE001]/g, ""); }

    var NET = [
        /* 调用处包起来的。没合上的一段算到行尾：slice() 切掉了结尾的记号，也不能把后面漏出去。 */
        [/\uE000[^\uE001]*(?:\uE001|$)/g, "…"],
        [/[\uE000\uE001]/g, ""],
        /* 这个项目的日志把名字（群、片子、字幕文件、搜索词、海报）都括在「」里：没包的也当名字。 */
        [/「[^」]*」/g, "「…」"],
        /* 地址：网页链接、列表、站点规则看过的网站是谁的隐私；tg:// 是扫码登录的令牌。 */
        [/\b(?:https?|tg):\/\/[^\s"'<>」）)，,]+/g, "…"],
        /* Telegram 用户 ID、网站账号编号（「id=8773…」「账号编号 7」） */
        [/\b(id ?[=:：] ?)-?\d{4,}/g, "$1…"],
        [/(账号编号 ?)[^\s，,；;）)]+/g, "$1…"],
        /* 32 位以上的十六进制串：API Hash、令牌，读日志的人用不上。 */
        [/\b[0-9a-f]{32,}\b/gi, "…"]
    ];

    function scrub(s) {
        var out = String(s == null ? "" : s);
        for (var i = 0; i < NET.length; i++) { out = out.replace(NET[i][0], NET[i][1]); }
        return out;
    }

    /* ---------------- 那一圈 ---------------- */

    function pad(n) { return n < 10 ? "0" + n : String(n); }
    function stamp() {
        var d = new Date();
        return pad(d.getMonth() + 1) + "-" + pad(d.getDate()) + " " +
               pad(d.getHours()) + ":" + pad(d.getMinutes()) + ":" + pad(d.getSeconds());
    }

    function load() {
        if (loaded) { return; }
        loaded = true;
        var kept = parse(get(K_RING));
        if (kept && kept.length) {
            ring = kept.slice(-MAX_LINES);
            for (var i = 0; i < ring.length; i++) { chars += String(ring[i]).length; }
        }
    }

    function persist() {
        if (persistTimer) { clearTimeout(persistTimer); persistTimer = null; }
        if (!enabled()) { return; }
        put(K_RING, JSON.stringify(ring));
    }

    function push(line) {
        load();
        if (line.length > MAX_LINE) { line = line.slice(0, MAX_LINE) + "…（这一行太长，截在 " + MAX_LINE + " 字）"; }
        ring.push(line);
        chars += line.length;
        while (ring.length > 1 && (ring.length > MAX_LINES || chars > MAX_CHARS)) { chars -= ring.shift().length; }
        if (!persistTimer) { persistTimer = setTimeout(persist, PERSIST_EVERY); }
    }

    function record(kind, detail) {
        if (!enabled()) { return; }
        try { push(stamp() + " " + scrub(kind + ": " + detail)); } catch (e) {}
    }

    /* ---------------- 上传 ---------------- */

    var ALPHABET = "ABCDEFGHJKMNPQRSTVWXYZ23456789";   /* 没有 0/O、1/I/L、U：要从屏幕上念出来 */
    function deviceId() {
        var id = get(K_DEVICE);
        if (id && /^[A-Z2-9]{8}$/.test(id)) { return id; }
        id = "";
        var bytes = null;
        try { bytes = new Uint8Array(8); window.crypto.getRandomValues(bytes); } catch (e) { bytes = null; }
        for (var i = 0; i < 8; i++) {
            var r = bytes ? bytes[i] : Math.floor(Math.random() * 256);
            id += ALPHABET.charAt(r % ALPHABET.length);
        }
        put(K_DEVICE, id);
        return id;
    }
    function shown(id) { return id.slice(0, 4) + "-" + id.slice(4); }

    function today() {
        var d = new Date();
        return d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate());
    }
    function sentState() {
        var s = parse(get(K_SENT)) || {};
        if (s.day !== today()) { s = { day: today(), n: 0, at: 0, manualAt: s.manualAt || 0 }; }
        return s;
    }

    function post(url, body, cb) {
        var finished = false;
        function end(status, text) { if (!finished) { finished = true; cb(status, text); } }
        try {
            var xhr = new XMLHttpRequest();
            xhr.open("POST", url, true);
            /* text/plain 让它是个简单请求：会发预检的引擎上也不发。 */
            xhr.setRequestHeader("Content-Type", "text/plain;charset=UTF-8");
            xhr.timeout = 20000;
            xhr.onreadystatechange = function () {
                if (xhr.readyState === 4) { end(xhr.status, xhr.responseText); }
            };
            xhr.ontimeout = function () { end(0, "超时"); };
            xhr.onerror = function () { end(0, "连不上"); };
            xhr.send(body);
        } catch (e) { end(0, "发不出去：" + (e && e.message)); }
    }

    function versions() {
        try { return Boot.info(); } catch (e) { return { packaged: "", running: "" }; }
    }

    /* reason：为什么传这一份，用观众看到的那句话。 */
    function send(reason, manual, done) {
        done = done || function () {};
        /* 手动按的要在设置页那行字里有个回答，所以每一种结局 —— 包括这里就拒了的 —— 都记进 last。 */
        function refuse(why) {
            if (manual) { last = { at: now(), ok: false, why: why, manual: true }; }
            done({ ok: false, why: why });
        }
        if (!enabled()) { refuse("诊断日志关着"); return; }
        var url = endpoint();
        if (!url) { refuse("这个版本没有接收地址"); return; }
        if (sending) { refuse("正在上传上一份"); return; }
        var t = now(), s = sentState();
        if (manual) {
            if (t - (s.manualAt || 0) < MANUAL_GAP) { refuse("刚传过，过几秒再按"); return; }
            s.manualAt = t;
        } else {
            if (t - (s.at || 0) < AUTO_GAP) {
                report("diag", "没传（三分钟内自动传过一份）：" + reason);
                done({ ok: false, why: "三分钟内传过" });
                return;
            }
            if (s.n >= AUTO_PER_DAY) {
                report("diag", "没传（今天已经自动传了 " + s.n + " 份）：" + reason);
                done({ ok: false, why: "今天传够了" });
                return;
            }
            s.n++;
            s.at = t;
        }
        put(K_SENT, JSON.stringify(s));

        load();
        var v = versions();
        var body = JSON.stringify({
            v: 1, app: APP, device: deviceId(),
            version: v.packaged || "", running: v.running || "",
            reason: scrub(reason).slice(0, 300), manual: !!manual,
            tvAt: t, tz: new Date().getTimezoneOffset(),
            ua: String(navigator.userAgent || "").slice(0, 300),
            lines: ring.slice()
        });
        persist();
        sending = true;
        var lines = ring.length;
        post(url, body, function (status, text) {
            /* 老电视的根证书未必认得接收端的证书，而最需要诊断的恰恰是老电视。https 在网络层失败就用 http
             * 再试一次，日志里写走的是哪条 —— 只有这样才知道这条退路到底用不用得上。 */
            if (status === 0 && /^https:/.test(url)) {
                post("http:" + url.slice(6), body, function (s2, t2) { finish(s2, t2, "http（https " + text + "）"); });
                return;
            }
            finish(status, text, /^https:/.test(url) ? "https" : "http");
        });
        function finish(status, text, via) {
            sending = false;
            var res = parse(text) || {};
            if (status >= 200 && status < 300 && res.id) {
                last = { at: now(), ok: true, id: res.id, manual: !!manual };
                report("diag", "传了 " + lines + " 行，编号 " + res.id + "，走 " + via + "（" + reason + "）");
                done({ ok: true, id: res.id });
            } else {
                var why = status ? "HTTP " + status + (res.error ? " " + res.error : "") : String(text || "连不上");
                last = { at: now(), ok: false, why: why, manual: !!manual };
                report("diag", "没传上：" + why + "，走 " + via + "（" + reason + "）");
                done({ ok: false, why: why });
            }
        }
    }

    function incident(reason) {
        if (!enabled() || !endpoint()) { return; }
        reasons.push(String(reason || "?").slice(0, 120));
        if (settleTimer) { return; }
        settleTimer = setTimeout(function () {
            settleTimer = null;
            var why = reasons.join(" / ");
            reasons = [];
            send(why, false);
        }, SETTLE);
    }

    if (typeof document !== "undefined" && document.addEventListener) {
        /* Tizen 多半是挂起而不是杀进程；藏起来的页面可能再也跑不到那个 15 秒的定时器。 */
        try {
            document.addEventListener("visibilitychange", function () {
                if (document.hidden) { persist(); }
            });
            window.addEventListener("pagehide", persist);
        } catch (e) {}
    }

    return {
        priv: priv,
        plain: plain,
        scrub: scrub,
        record: record,
        incident: incident,
        /* app.js 的 window.onload 里调：日志通道，再记一行分界，留下来的那一圈看得出哪次启动从哪开始。 */
        init: function (opts) {
            if (opts && opts.report) { report = opts.report; }
            if (enabled()) { push(stamp() + " diag: —— 新的一次启动 ——"); }
        },
        upload: function (done) { send("在设置里手动上传", true, done); },
        enabled: enabled,
        setEnabled: function (on) {
            if (on) { del(K_OFF); return; }
            put(K_OFF, "1");
            ring = []; chars = 0; reasons = [];
            if (settleTimer) { clearTimeout(settleTimer); settleTimer = null; }
            if (persistTimer) { clearTimeout(persistTimer); persistTimer = null; }
            del(K_RING);
        },
        status: function () {
            return { enabled: enabled(), configured: !!endpoint(), device: shown(deviceId()),
                     lines: (load(), ring.length), sending: sending || !!settleTimer, last: last };
        },
        _test: { NET: NET, endpoint: endpoint, ring: function () { return ring.slice(); },
                 SETTLE: SETTLE, AUTO_GAP: AUTO_GAP, AUTO_PER_DAY: AUTO_PER_DAY }
    };
})();

