                if (op.remove) { T.sb.remove(op.remove[0], op.remove[1]); T.removing = op; }
                else { T.sb.appendBuffer(op.buf); T.full = false; if (op.t !== undefined) { T.lastT = op.t; } }
                T.q.shift();
