/* 电视本地存的东西：
 * - 看到哪里（localStorage，抖音那边实测活得过重装）：fileKey → {t, d, at, title}
 * - 上次看的来源
 * - moov 缓存（IndexedDB，按最近用过留 12 个）：长片的 moov 有几 MB，下一次要 2.5–4 秒，续播时省掉 */
var Store = (function () {
    "use strict";

    /* 每人一份的键（accounts.js：第一个账号就是原来的键名，后加的带 @a2 之类）；整台电视共用的直接用键名 */
