    }

    function getMoov(key) { return get("moov", key); }
    /* MP4：{start, bytes}（moov 原样）；MKV：{mkv: info}（mkv.js 解析好的头 + Cues，结构化克隆存进去） */
    function putMoov(key, m) { return put("moov", key, m.mkv ? { mkv: m.mkv } : { start: m.start, bytes: m.bytes }, 12); }
